rsity.", "children": [{"id": "ef7dbe91-eb34-4ae4-9550-13ac233ac80b", "type": "subtopic", "title": "From writings to scripture", "children": [{"id": "5bd4dce3-cd2f-48e2-8d45-8c701c299390", "type": "concept", "title": "Apostolicity"}, {"id": "12ea38b8-f4b3-4c0b-adc7-38cb6ce0ae16", "type": "concept", "title": "Orthodoxy"}, {"id": "c5596fdd-08b0-4288-9c0a-1938f974e586", "type": "concept", "title": "Catholicity"}, {"id": "04390074-c45c-4939-a9a5-fa21b7bfcfac", "type": "concept", "title": "Liturgical use"}], "description": "Canon formation was a historical process involving use, debate, authority, and community practice."}, {"id": "49060c19-503e-477d-afe5-829857af6696", "type": "subtopic", "title": "Early Christian diversity", "children": [{"id": "46b3bda0-1f85-478b-b879-1432a58f5f72", "type": "concept", "title": "Jewish followers of Jesus"}, {"id": "18ae7907-a6f0-4f9f-ad28-7aa50f42ebfb", "type": "concept", "title": "Gentile assemblies"}, {"id": "2036c23a-ca51-4e71-807f-b7f7097dca36", "type": "concept", "title": "Gnostic texts"}, {"id": "7b112f56-4e58-4ca3-bf58-0cd4edb2b21b", "type": "concept", "title": "Proto-orthodoxy"}], "description": "Diversity helps students see that early Christianity included many communities, texts, and theological debates."}, {"id": "2065e436-0ae7-4600-a268-9d67cedd56b6", "type": "subtopic", "title": "Noncanonical writings", "children": [{"id": "cbb8857b-137b-41ab-989d-d3889bba82e2", "type": "concept", "title": "Gospel of Thomas"}, {"id": "c998e971-07e6-47f3-8780-35b84060613c", "type": "concept", "title": "Infancy gospels"}, {"id": "293e2cda-a6b5-40fa-839d-c6b0cc0d2c78", "type": "concept", "title": "Apostolic Fathers"}, {"id": "6751b5f4-70a4-465b-bfb3-14e404ec919d", "type": "concept", "title": "Acts of Paul and Thecla"}], "description": "Noncanonical texts illuminate early Christian imagination and boundary making."}]}, {"id": "18e01ac4-4e47-46ec-be72-50dac70fa59e", "type": "topic", "title": "Textual Criticism and the Material History of the New Testament", "description": "Learn how scholars compare manuscripts and evaluate variants to reconstruct textual histories.", "children": [{"id": "94d8c904-6935-4814-acf8-2176f9a0a407", "type": "subtopic", "title": "Manuscript evidence", "children": [{"id": "18938e12-df00-4df0-9f70-b5996555c683", "type": "concept", "title": "Papyri"}, {"id": "ad0de13d-53e9-428c-be70-6afcb3bce809", "type": "concept", "title": "Codices"}, {"id": "8dc34845-f5b9-4f21-a429-26fd63c1783c", "type": "concept", "title": "Minuscules"}, {"id": "fb60af73-f5dd-4e97-9fd0-6bde5479d8ad", "type": "concept", "title": "Lectionaries"}], "description": "Textual criticism begins with real material witnesses copied by real scribes."}, {"id": "59c19763-1437-424e-bba4-7aa5dc0f2fab", "type": "subtopic", "title": "Textual variants", "children": [{"id": "289a9f5a-466c-486c-b189-fbdbdc82c9c3", "type": "concept", "title": "Accidental errors"}, {"id": "18c4a87b-9e3a-4cd8-a181-10c85e253f1c", "type": "concept", "title": "Intentional changes"}, {"id": "accc1b33-bf10-42e1-a15e-86a6e5d16b6d", "type": "concept", "title": "External evidence"}, {"id": "970de081-0aae-41d1-8a1f-f45fc20dfff9", "type": "concept", "title": "Internal evidence"}], "description": "Variants show where manuscripts differ and what those differences mean for interpretation."}, {"id": "2bbfc649-2e94-4641-a860-aadd2336029a", "type": "subtopic", "title": "Critical editions", "children": [{"id": "50e820a7-0648-492b-88b9-161148201c2d", "type": "concept", "title": "Nestle-Aland"}, {"id": "7a9b7060-3529-47e7-b8fc-2ce6c0d2d224", "type": "concept", "title": "United Bible Societies edition"}, {"id": "b2cfb7b1-6063-476c-8ae7-83856ce5813c", "type": "concept", "title": "Apparatus symbols"}, {"id": "3fb66e2c-82c8-4918-8d60-e4e6dfd74d36", "type": "concept", "title": "Translation footnotes"}], "description": "Students learn how modern editions and apparatuses present evidence and decisions."}]}, {"id": "8c6573d2-01b5-44fc-9e75-7934a52779ea", "type": "topic", "title": "Exegesis, Hermeneutics, and Close Reading", "description": "Practice disciplined interpretation using context, genre, language, argument, and reception.", "children": [{"id": "d6831844-6aae-43db-bd37-76e28aa371da", "type": "subtopic", "title": "Close reading", "children": [{"id": "0fbbe507-147f-43f7-aaf5-75b41f3ea5f4", "type": "concept", "title": "Structure"}, {"id": "382fad91-59af-44a9-b35c-0912742562ea", "type": "concept", "title": "Key terms"}, {"id": "46e1222b-e234-4779-94ec-37b49e6bb8f8", "type": "concept", "title": "Repetition"}, {"id": "67ea252d-6367-4df0-a11a-603cdbe2895d", "type": "concept", "title": "Narrative voice"}], "description": "Close reading trains students to observe details before jumping to conclusions."}, {"id": "3230a9b0-094d-4b5f-8cc3-c56551fb3e76", "type": "subtopic", "title": "Contextual interpretation", "children": [{"id": "5a31628c-94de-429f-8509-652c1eb510a4", "type": "concept", "title": "Genre"}, {"id": "21deee7a-b356-44c7-b9c3-b5935afe14af", "type": "concept", "title": "Audience"}, {"id": "e726f239-3cf3-4f1d-9763-f46177e30f05", "type": "concept", "title": "Intertextuality"}, {"id": "276d34ee-95f3-464d-9159-cbb33b01336e", "type": "concept", "title": "Social setting"}], "description": "Interpretation becomes stronger when textual observations meet historical and literary context."}, {"id": "c115f6c7-c1b3-454a-9beb-6487a1f3af3b", "type": "subtopic", "title": "Hermeneutical reflection", "children": [{"id": "daca92ac-3a0d-4225-94ab-eb5422210b2b", "type": "concept", "title": "Author and audience"}, {"id": "950d3f83-c58e-4252-b6cf-18ab8ddd44e6", "type": "concept", "title": "Reception"}, {"id": "db6c741d-a2fc-48c2-b30d-727eb07f739e", "type": "concept", "title": "Reader assumptions"}, {"id": "202a32b8-1eae-4ee7-8e60-b2958fbe9c37", "type": "concept", "title": "Interpretive communities"}], "description": "Hermeneutics asks how meaning is made across text, context, tradition, and reader."}]}, {"id": "300e9b22-7558-41f7-8193-9f45f34160a7", "type": "topic", "title": "New Testament Theology, Ethics, and Social World", "description": "Study themes such as kingdom, salvation, law, grace, gender, slavery, poverty, empire, and community life.", "children": [{"id": "c0cd0424-ca9d-46c9-b269-b578bc48813c", "type": "subtopic", "title": "Theological themes", "children": [{"id": "396e734b-e784-4186-b5d3-1a6bc247e1db", "type": "concept", "title": "Kingdom of God"}, {"id": "671c9272-f0a9-4908-b4df-fc39ca744544", "type": "concept", "title": "Christology"}, {"id": "fe1948ee-fb67-4099-801c-4e5c884ebff8", "type": "concept", "title": "Salvation"}, {"id": "49a16fe3-0b07-4bd3-842a-8308db126790", "type": "concept", "title": "Law and grace"}], "description": "Students compare themes across texts without flattening differences among authors."}, {"id": "df279b6f-55d1-4334-ae02-47789323e5b5", "type": "subtopic", "title": "Ethics and community life", "children": [{"id": "19e34480-7b49-4b2f-9c4c-a9f8230fdba1", "type": "concept", "title": "Wealth and poverty"}, {"id": "fb4209f5-0f1a-4b7e-91e2-cfb3f72915da", "type": "concept", "title": "Sexual ethics"}, {"id": "065049be-796e-4940-be30-68dc8fb040c1", "type": "concept", "title": "Forgiveness"}, {"id": "29b6ff21-3034-4bf2-9c3d-d355f384873a", "type": "concept", "title": "Community discipline"}], "description": "Ethical texts must be read in ancient context and with attention to later reception."}, {"id": "31253a14-9e2c-41e5-b257-5d4c9e2904f2", "type": "subtopic", "title": "Social world of early Christianity", "children": [{"id": "c0fa86ee-ef58-4cfb-b864-75b9a873f684", "type": "concept", "title": "House churches"}, {"id": "b9289acf-6963-44b9-9c25-1b065e20eb23", "type": "concept", "title": "Patronage"}, {"id": "00770073-9051-4620-8891-6dc2c1fc2cfb", "type": "concept", "title": "Slavery"}, {"id": "da45ce18-744c-492e-8399-285582a67374", "type": "concept", "title": "Gender and leadership"}], "description": "The social world clarifies how households, status, gender, slavery, and empire appear in the texts."}]}, {"id": "20d08f91-0dd5-4c99-ac5c-593c7ec67d5b", "type": "topic", "title": "Reception History, Art, Liturgy, and Interpretation", "description": "Trace how New Testament texts have been interpreted in worship, doctrine, art, politics, literature, and public life.", "children": [{"id": "c846e872-9a7a-439b-a3bd-68dcc9ab1e0d", "type": "subtopic", "title": "Reception history", "children": [{"id": "d02ab118-39d9-4f76-afee-e388ad683e50", "type": "concept", "title": "Patristic interpretation"}, {"id": "c17c034a-0d50-458e-96f6-1b30da33f514", "type": "concept", "title": "Medieval exegesis"}, {"id": "51e37c7c-fde1-4be7-8f05-aeec72e7cb4e", "type": "concept", "title": "Reformation debates"}, {"id": "37c6f561-7254-4d24-bf95-cd9c6df52b44", "type": "concept", "title": "Modern scholarship"}], "description": "Reception history shows how New Testament texts have lived in communities, institutions, and cultures."}, {"id": "40a6ddb5-fe5c-4072-bfcf-b09548ee4967", "type": "subtopic", "title": "Art and material reception", "children": [{"id": "99ab1fd2-3bd4-4c8d-8153-4c5bce6baac9", "type": "concept", "title": "Iconography"}, {"id": "c7135d53-163c-4fc1-b3c3-33039dfdd125", "type": "concept", "title": "Manuscript illumination"}, {"id": "1ebf5f93-6bb1-4b86-8830-6c74ea0d615e", "type": "concept", "title": "Architecture"}, {"id": "233f0355-c45b-40d4-89b0-8ea6bc211ac9", "type": "concept", "title": "Film and media"}], "description": "Images and objects reveal how communities visualized and taught New Testament stories."}, {"id": "b9c88241-643c-44d0-8431-3c537ce5ea23", "type": "subtopic", "title": "Liturgy and public life", "children": [{"id": "1bf0aff3-7214-4e4a-bd06-1eddf57bedfa", "type": "concept", "title": "Lectionaries"}, {"id": "e3f33f53-f7f3-49e0-bf5f-31aeae96c22e", "type": "concept", "title": "Creeds"}, {"id": "4953a901-cb40-4ed1-87d0-095a756dc9e6", "type": "concept", "title": "Abolition and civil rights"}, {"id": "74cd3d92-99a0-438f-be6c-e5611eada699", "type": "concept", "title": "Contemporary debates"}], "description": "New Testament texts shape worship, ethics, politics, law, and social movements."}]}, {"id": "fd0116c6-d651-4d63-bfbf-e8aa4c42e17f", "type": "topic", "title": "Archaeology, Material Culture, and Digital Biblical Studies", "description": "Use artifacts, inscriptions, geography, manuscripts, and digital tools to enrich textual interpretation.", "children": [{"id": "0fd77117-2dc0-431b-86ca-040e8775c9a7", "type": "subtopic", "title": "Archaeology and geography", "children": [{"id": "936d31ac-1b69-4e01-863a-3a397ce30e30", "type": "concept", "title": "Jerusalem"}, {"id": "477fd11b-e75a-40ad-9f4c-42ce7034e65f", "type": "concept", "title": "Galilee"}, {"id": "c40b142a-1260-4503-aae6-56bcd19655e8", "type": "concept", "title": "Corinth"}, {"id": "53e1e47f-fe7b-4d62-b4a7-375573d2cd1e", "type": "concept", "title": "Ephesus"}], "description": "Material context helps students imagine places, travel, cities, and daily life more accurately."}, {"id": "c8312497-254a-4a03-a015-e03022583980", "type": "subtopic", "title": "Inscriptions and artifacts", "children": [{"id": "12a650ba-05dd-44e9-8963-da590f2bc642", "type": "concept", "title": "Imperial inscriptions"}, {"id": "13a44f82-3f10-43cd-966c-ae62df473d1f", "type": "concept", "title": "Synagogues"}, {"id": "902b56fc-0f2a-4be7-b8d8-83b8e9906ef9", "type": "concept", "title": "House churches"}, {"id": "54f833b3-0a97-46ea-ac42-96e5f4ad00fc", "type": "concept", "title": "Coins and titles"}], "description": "Inscriptions, coins, architecture, and household objects illuminate social and political context."}, {"id": "efc78ad0-8a02-45ed-a81b-79d2e5d7bc0a", "type": "subtopic", "title": "Digital tools", "children": [{"id": "cca91cf8-6949-42dc-bd74-d507005fd9c6", "type": "concept", "title": "Bible software"}, {"id": "2534279d-666a-4e19-941c-f75bcba8a24c", "type": "concept", "title": "Manuscript databases"}, {"id": "3eca6c6f-8f4b-4692-ae59-8a96ee68bd18", "type": "concept", "title": "Digital maps"}, {"id": "fc2e52b2-43cf-4bc6-b2f7-ac115866b7c5", "type": "concept", "title": "Text search and concordance tools"}], "description": "Digital tools support close reading, manuscript study, mapping, and responsible comparison."}]}, {"id": "f8f1701e-9955-4887-857c-af9b6ec227a1", "type": "topic", "title": "Contemporary Scholarship, Debate, and Responsible Interpretation", "description": "Engage current scholarly debates while practicing respectful, evidence-based, non-devotional academic analysis.", "children": [{"id": "f304b8d9-f6cb-4221-819d-c08cf79da5aa", "type": "subtopic", "title": "Major scholarly debates", "children": [{"id": "a144b08f-ec5c-4625-a475-3a988d569690", "type": "concept", "title": "Historical Jesus debates"}, {"id": "6f5e7581-b99c-46f4-ab00-a7c675f2e6c6", "type": "concept", "title": "Paul and Judaism"}, {"id": "dfd18ba1-d6d4-4961-8a9e-11fdbeac262f", "type": "concept", "title": "Empire criticism"}, {"id": "bb314f95-8423-4de0-9c8e-e81ba99fd17d", "type": "concept", "title": "Memory studies"}], "description": "Students learn that New Testament studies is an active field with contested evidence and methods."}, {"id": "69e8c356-4577-4eb5-a04b-e33254a636ea", "type": "subtopic", "title": "Responsible academic disagreement", "children": [{"id": "40d275a7-4562-4eda-9193-df622f2f2bec", "type": "concept", "title": "Argument quality"}, {"id": "9e6b72bc-8241-4c22-b853-f8a63644820e", "type": "concept", "title": "Source evaluation"}, {"id": "17940764-4562-4422-a93b-bfcaebe78c6a", "type": "concept", "title": "Respectful critique"}, {"id": "6f8f94dd-1bd7-4281-8da4-a73d477bbdf1", "type": "concept", "title": "Avoiding caricature"}], "description": "World-class study requires charity, evidence, precision, and awareness of stakes."}, {"id": "0511066f-daa6-4ab6-aa26-26b5737f936c", "type": "subtopic", "title": "Public interpretation", "children": [{"id": "a737cfbe-24aa-446d-b2f5-acb4188021b5", "type": "concept", "title": "Popular media"}, {"id": "ce836821-95a1-44ec-b6ce-575fa807