set
  title = 'Introduction to the New Testament',
  goal = 'Introduction to the New Testament',
  summary = 'Introduce the New Testament as a collection of ancient texts studied historically, literarily, religiously, and ethically. Students learn how the collection was transmitted and canonized, place Jesus, Paul, and early communities in Jewish and Greco-Roman contexts, read the Gospels, Acts, letters, and Revelation with critical methods, and practice exegesis, reception history, material and digital study, and responsible interpretation in a research capstone.',
