e": "subtopic", "title": "Jesus in Galilee and Judea", "children": [{"id": "bff174b3-4df2-476f-b457-4e6bbf8b0ef6", "type": "concept", "title": "Galilee"}, {"id": "bfaca58c-db5f-4146-a0f5-689d4e8c4320", "type": "concept", "title": "Jerusalem"}, {"id": "09f664d5-f388-4504-b229-811ad7b020ce", "type": "concept", "title": "Temple conflict"}, {"id": "c15ae252-5132-4da7-ac53-2c2f61289287", "type": "concept", "title": "Roman occupation"}], "description": "Students place Jesus within rural, urban, religious, and political landscapes of first-century Palestine."}, {"id": "76e3effa-4831-4440-aba0-ec2284d5c1c5", "type": "subtopic", "title": "Jesus traditions", "children": [{"id": "14e9b575-ca6d-4833-97ed-93b77b1b10a3", "type": "concept", "title": "Parables"}, {"id": "4fe39a39-6721-4e6e-a58a-a402efa7f544", "type": "concept", "title": "Miracles"}, {"id": "6dedf1ac-c33c-43ca-b80e-f2e8169e60ab", "type": "concept", "title": "Kingdom of God"}, {"id": "ce4c816e-3e56-48c3-981c-39f2a87ff3d6", "type": "concept", "title": "Passion traditions"}], "description": "Jesus traditions were remembered, performed, adapted, and written in different communities."}]}, {"id": "780d88eb-21e8-4879-93f2-79f9c4f564d2", "type": "topic", "title": "Synoptic Gospels and the Synoptic Problem", "description": "Read Mark, Matthew, and Luke as distinct literary and theological portraits shaped by shared traditions.", "children": [{"id": "970a4d30-e69c-45e4-9d4f-12c077b5c91b", "type": "subtopic", "title": "Mark", "children": [{"id": "cf93d609-f60e-4ce1-ae4e-f4fd84e64226", "type": "concept", "title": "Messianic secret"}, {"id": "86d97f6e-c2b2-4c54-8a67-4069c3c1dd06", "type": "concept", "title": "Discipleship"}, {"id": "eb493d9d-84a1-4cc5-88f4-4889385b7266", "type": "concept", "title": "Passion narrative"}, {"id": "64264c8f-f524-4519-b9c6-c66eeffaf7be", "type": "concept", "title": "Apocalyptic discourse"}], "description": "Mark introduces students to Gospel as narrative shaped by urgency, secrecy, conflict, and suffering."}, {"id": "42c250bc-6999-4e68-9978-e980fa62f09b", "type": "subtopic", "title": "Matthew and Luke", "children": [{"id": "3e787736-d876-44f4-9f57-e02c487aebd4", "type": "concept", "title": "Matthew and Torah"}, {"id": "3de5b9b9-0452-4a40-8839-6297a5d18761", "type": "concept", "title": "Luke and the marginalized"}, {"id": "c6c89ee1-5d49-4546-a162-8a5d0691983d", "type": "concept", "title": "Infancy narratives"}, {"id": "429d9564-65df-48ed-9b44-9bafd12f96ae", "type": "concept", "title": "Genealogies"}], "description": "Matthew and Luke show how shared traditions can be reshaped for different communities and theological aims."}, {"id": "6132c6cc-69cf-4ea1-b56c-1e0a32c414d0", "type": "subtopic", "title": "Synoptic problem", "children": [{"id": "f3d503be-334b-4a43-9dd8-59619c5a990e", "type": "concept", "title": "Markan priority"}, {"id": "28155257-f99f-4d38-88ac-656b761d00dc", "type": "concept", "title": "Q hypothesis"}, {"id": "3138706c-fabf-44de-bb86-1555ae5af3d1", "type": "concept", "title": "Two-source theory"}, {"id": "fe6c692a-d452-49db-b126-abe8fba7d7cb", "type": "concept", "title": "Minor agreements"}], "description": "The Synoptic Problem teaches students how scholars explain literary relationships among the Gospels."}]}, {"id": "a534695a-e7b6-4675-85f6-aa6705f63623", "type": "topic", "title": "The Gospel of John and Johannine Tradition", "description": "Study John's distinctive language, symbolism, Christology, community setting, and interpretive challenges.", "children": [{"id": "fa81e52e-864a-4f78-9486-96ef9413b323", "type": "subtopic", "title": "Johannine style and symbolism", "children": [{"id": "f376f667-6291-403a-9c3e-5974d57380bc", "type": "concept", "title": "Word/Logos"}, {"id": "f0dbeaf0-1e65-4aaf-860e-94c96d8d31e3", "type": "concept", "title": "Signs"}, {"id": "2cf9b879-dd58-4ab5-bd5a-45905daf42c5", "type": "concept", "title": "I am sayings"}, {"id": "776b7ed8-2b74-4dbd-90a5-eb576ba29059", "type": "concept", "title": "Light and darkness"}], "description": "John uses distinctive language, signs, speeches, and symbols to interpret Jesus."}, {"id": "4454543e-b744-40c0-8b49-05b08feef0fc", "type": "subtopic", "title": "Johannine community and conflict", "children": [{"id": "ae5e17a2-9fe8-4b35-9308-11b391f414a9", "type": "concept", "title": "Belief and unbelief"}, {"id": "11f8f383-34fc-49ef-ad2d-6c6f4082f002", "type": "concept", "title": "Judean authorities"}, {"id": "9098d0f2-01b6-4f24-a024-2254f220125d", "type": "concept", "title": "Community boundaries"}, {"id": "3536d7ed-3164-42ab-bfc1-68edb336b116", "type": "concept", "title": "Love commandment"}], "description": "Students examine how community identity, conflict, and belief shape the Gospel's rhetoric."}, {"id": "ffae1ece-251b-4496-b618-2a0e28315d05", "type": "subtopic", "title": "John and the Synoptics", "children": [{"id": "0ad0d2ae-5801-4477-9130-b27baf5a718b", "type": "concept", "title": "Temple chronology"}, {"id": "6c820a90-1329-4400-a8b5-ba90180e44c1", "type": "concept", "title": "Passover themes"}, {"id": "2b038a56-2bc1-4028-ba06-4b5dc07d1a27", "type": "concept", "title": "High Christology"}, {"id": "3bcfc106-f650-441c-9b87-a8b173bb2b70", "type": "concept", "title": "Farewell discourse"}], "description": "Comparing John with the Synoptics clarifies difference in chronology, style, theology, and portrait of Jesus."}]}, {"id": "d64a892e-5f13-4470-8114-1bd7868993e0", "type": "topic", "title": "Acts, Mission, and Early Christian Expansion", "description": "Examine Acts as narrative theology, ancient historiography, and a key source for early Christian identity.", "children": [{"id": "8923f418-d5d5-4046-868e-4c4c06ca77e4", "type": "subtopic", "title": "Acts as narrative", "children": [{"id": "b4b5e3e5-c1df-4e2e-ab8c-82d2ae5cca93", "type": "concept", "title": "Jerusalem"}, {"id": "892cefd5-b8e6-4986-a3f8-6b83a4b4af54", "type": "concept", "title": "Samaria"}, {"id": "104814ef-0ab5-406a-a430-8a65ddc5ce2f", "type": "concept", "title": "Antioch"}, {"id": "5f01a909-5c7a-48cf-a84c-f2d9e8b744c9", "type": "concept", "title": "Rome"}], "description": "Acts tells a story of witness, conflict, travel, speeches, and the spread of the movement."}, {"id": "95c2de13-1ed3-4acc-b34e-62f8e977b1ab", "type": "subtopic", "title": "Mission and identity", "children": [{"id": "c7e7188d-f6ef-4f2e-94ae-18c2e2e20b40", "type": "concept", "title": "Pentecost"}, {"id": "15239c43-7192-474f-8123-e24a04e84266", "type": "concept", "title": "Cornelius"}, {"id": "14a4f151-ac76-4d24-ab16-c7299c32e3e0", "type": "concept", "title": "Jerusalem council"}, {"id": "037e27ac-029f-4202-8220-b604b9798bca", "type": "concept", "title": "Gentile mission"}], "description": "Acts explores how Jewish and gentile believers negotiate identity, scripture, law, and table fellowship."}, {"id": "3f85313a-63a7-414d-8f01-d87ebdf7e2cb", "type": "subtopic", "title": "History and theology", "children": [{"id": "8b11e717-2ae5-489a-9e6a-ac3a0a016472", "type": "concept", "title": "Ancient historiography"}, {"id": "0019ec7a-ebb5-44e0-b6a5-a53f538f1496", "type": "concept", "title": "Speeches"}, {"id": "1602690e-a826-4fb3-a2ce-cf9fb47cf3b9", "type": "concept", "title": "Miracle stories"}, {"id": "715727c9-f828-48d9-863c-e2bbd716f6fb", "type": "concept", "title": "Paul in Acts vs Paul in letters"}], "description": "Students learn to read Acts both as a historical source and as theological narrative."}]}, {"id": "8a5e4f49-2575-443e-b778-23490e785567", "type": "topic", "title": "Paul, Pauline Letters, and Early Christian Communities", "description": "Study Paul's letters as occasional writings that address communities, conflict, theology, ethics, and identity.", "children": [{"id": "58376376-5ef2-4a8a-8088-e0bbf1def2a9", "type": "subtopic", "title": "Paul's life and letters", "children": [{"id": "170531bd-53e6-4042-bd54-081a2e520b2b", "type": "concept", "title": "Authentic letters"}, {"id": "e8669dbf-df5c-4a0a-aef5-667e67e04ea1", "type": "concept", "title": "Travel and mission"}, {"id": "f3a4a8b4-3ee1-421c-9e7c-57df794eccad", "type": "concept", "title": "Occasional correspondence"}, {"id": "b340c0c2-2b10-4abc-b76f-dc4d5185aa17", "type": "concept", "title": "Rhetorical situation"}], "description": "Paul's letters are occasional writings responding to real communities and conflicts."}, {"id": "69d664a1-28f1-437f-8a33-8446970c1083", "type": "subtopic", "title": "Major Pauline themes", "children": [{"id": "43ac0952-f337-4bd3-8981-b4ee6f2efe59", "type": "concept", "title": "Justification"}, {"id": "06c703c1-6e94-4b39-a4fd-5d1c8370d1d9", "type": "concept", "title": "Faithfulness"}, {"id": "4ca2dac8-755b-4248-91f4-ffe4f237ce95", "type": "concept", "title": "Spirit"}, {"id": "f22aa321-d0fc-44db-997b-d92b28ec133a", "type": "concept", "title": "Body of Christ"}], "description": "Pauline interpretation requires careful attention to argument, metaphor, scripture, and community practice."}, {"id": "2610f884-462d-48ea-8f1a-d444a2916c7f", "type": "subtopic", "title": "Paul's communities", "children": [{"id": "da15ce5c-8ee4-41a3-8115-41848ed613ce", "type": "concept", "title": "Corinth"}, {"id": "cea0afa7-2618-4c76-a5e5-9dda445c0068", "type": "concept", "title": "Galatia"}, {"id": "97de710d-dfa9-4eed-a803-e8fe32b56667", "type": "concept", "title": "Philippi"}, {"id": "338a4aa2-4944-4383-9248-bb85863b8f7e", "type": "concept", "title": "Rome"}], "description": "Paul's letters reveal urban assemblies negotiating status, ethnicity, gender, wealth, worship, and ethics."}]}, {"id": "0ba84072-6eaa-4511-b5ca-774a837a0f29", "type": "topic", "title": "Deutero-Pauline, Pastoral, and Catholic Epistles", "description": "Explore disputed letters and general epistles as witnesses to developing authority, household order, ethics, and community boundaries.", "children": [{"id": "2584e30a-6dd5-49a4-8e00-ca5398e1780b", "type": "subtopic", "title": "Disputed Pauline letters", "children": [{"id": "61eddee0-30a2-469b-89e6-5b5346e7b1ae", "type": "concept", "title": "Ephesians"}, {"id": 