nd diversity.", "children": [{"id": "ef7dbe91-eb34-4ae4-9550-13ac233ac80b", "type": "subtopic", "title": "From writings to scripture", "children": [{"id": "5bd4dce3-cd2f-48e2-8d45-8c701c299390", "type": "concept", "title": "Apostolicity"}, {"id": "12ea38b8-f4b3-4c0b-adc7-38cb6ce0ae16", "type": "concept", "title": "Orthodoxy"}, {"id": "c5596fdd-08b0-4288-9c0a-1938f974e586", "type": "concept", "title": "Catholicity"}, {"id": "04390074-c45c-4939-a9a5-fa21b7bfcfac", "type": "concept", "title": "Liturgical use"}], "description": "Canon formation was a historical process involving use, debate, authority, and community practice."}, {"id": "49060c19-503e-477d-afe5-829857af6696", "type": "subtopic", "title": "Early Christian diversity", "children": [{"id": "46b3bda0-1f85-478b-b879-1432a58f5f72", "type": "concept", "title": "Jewish followers of Jesus"}, {"id": "18ae7907-a6f0-4f9f-ad28-7aa50f42ebfb", "type": "concept", "title": "Gentile assemblies"}, {"id": "2036c23a-ca51-4e71-807f-b7f7097dca36", "type": "concept", "title": "Gnostic texts"}, {"id": "7b112f56-4e58-4ca3-bf58-0cd4edb2b21b", "type": "concept", "title": "Proto-orthodoxy"}], "description": "Diversity helps students see that early Christianity included many communities, texts, and theological debates."}, {"id": "2065e436-0ae7-4600-a268-9d67cedd56b6", "type": "subtopic", "title": "Noncanonical writings", "children": [{"id": "cbb8857b-137b-41ab-989d-d3889bba82e2", "type": "concept", "title": "Gospel of Thomas"}, {"id": "c998e971-07e6-47f3-8780-35b84060613c", "type": "concept", "title": "Infancy gospels"}, {"id": "293e2cda-a6b5-40fa-839d-c6b0cc0d2c78", "type": "concept", "title": "Apostolic Fathers"}, {"id": "6751b5f4-70a4-465b-bfb3-14e404ec919d", "type": "concept", "title": "Acts of Paul and Thecla"}], "description": "Noncanonical texts illuminate early Christian imagination and boundary making."}]}, {"id": "18e01ac4-4e47-46ec-be72-50dac70fa59e", "type": "topic", "title": "Textual Criticism and the Material History of 